-- Integration tests use fabricated identities and roll back every record.
begin;
create function pg_temp.check_true(value boolean,label text) returns void language plpgsql as $$ begin if value is distinct from true then raise exception 'TEST FAILED: %',label; end if; end $$;
do $$
declare rid uuid:=gen_random_uuid();v jsonb;v2 jsonb;r jsonb;client_id uuid;venue_id uuid;blocked boolean;stamp text;attempt integer;
spec jsonb:='[{"name":"Test Client","email":"client@example.invalid","role":"client"},{"name":"Test Venue","email":"venue@example.invalid","role":"venue"}]';
begin
 perform pg_temp.check_true(not has_function_privilege('anon','public.venue_agreement_action(text,jsonb)','execute'),'anonymous RPC blocked');
 perform pg_temp.check_true(not has_table_privilege('anon','public.venue_agreement_signers','select'),'private signer table');
 insert into nsh_form_responses(id,form_id,answers,status) values(rid,'a3a383f7-e1db-4344-9dec-ea879ad3406d','{}','handled');
 v:=venue_agreement_action('draft',jsonb_build_object('response_id',rid,'title','Test-only Agreement','body',repeat('This is fabricated contract text used solely for a rollback test. ',5),'signers',spec));
 blocked:=false;begin perform venue_agreement_action('save',jsonb_build_object('version_id',v->>'id','expected_updated_at','stale','body','overwrite'));exception when others then blocked:=true;end;
 perform pg_temp.check_true(blocked,'stale draft edit rejected');
 v:=venue_agreement_action('issue',jsonb_build_object('version_id',v->>'id','expected_updated_at',v->>'updated_at','tokens','[{"hash":"test-client-v1"},{"hash":"test-venue-v1"}]'::jsonb));
 perform pg_temp.check_true(v->>'status'='pending','issue starts pending');
 blocked:=false;begin perform venue_agreement_action('save',jsonb_build_object('version_id',v->>'id','expected_updated_at',v->>'updated_at','body','tamper'));exception when others then blocked:=true;end;
 perform pg_temp.check_true(blocked,'issued text is locked');
 blocked:=false;begin perform venue_agreement_action('code','{"token_hash":"test-venue-v1","code_hash":"venue-code"}');exception when others then blocked:=true;end;
 perform pg_temp.check_true(blocked,'counter-signing waits for clients');
 perform venue_agreement_action('code','{"token_hash":"test-client-v1","code_hash":"client-code"}');
 for attempt in 1..5 loop r:=venue_agreement_action('sign',jsonb_build_object('token_hash','test-client-v1','code_hash','wrong','signed_name','Test Client','consent',true,'document_hash',v->>'document_hash'));end loop;
 perform pg_temp.check_true((select attempts=5 from venue_agreement_codes where signer_id=(select id from venue_agreement_signers where token_hash='test-client-v1')),'wrong code attempts persist');
 r:=venue_agreement_action('sign',jsonb_build_object('token_hash','test-client-v1','code_hash','client-code','signed_name','Test Client','consent',true,'document_hash',v->>'document_hash'));
 perform pg_temp.check_true(r?'error','locked challenge rejects correct code');
 delete from venue_agreement_codes where signer_id=(select id from venue_agreement_signers where token_hash='test-client-v1');
 perform venue_agreement_action('code','{"token_hash":"test-client-v1","code_hash":"client-code"}');
 blocked:=false;begin perform venue_agreement_action('sign',jsonb_build_object('token_hash','test-client-v1','code_hash','client-code','signed_name','Test Client','consent',true,'document_hash','wrong-version'));exception when others then blocked:=true;end;
 perform pg_temp.check_true(blocked,'signature bound to exact document hash');
 v:=venue_agreement_action('sign',jsonb_build_object('token_hash','test-client-v1','code_hash','client-code','signed_name','Test Client','consent',true,'document_hash',v->>'document_hash'));
 perform pg_temp.check_true(v->>'status'='pending','client signature alone does not complete contract');
 select id into client_id from venue_agreement_signers where version_id=(v->>'id')::uuid and role='client';
 blocked:=false;begin update venue_agreement_signers set signed_name='Changed signature' where id=client_id;exception when others then blocked:=true;end;
 perform pg_temp.check_true(blocked,'recorded client signature name cannot be edited');
 blocked:=false;begin update venue_agreement_signers set signed_at=now()+interval '1 day' where id=client_id;exception when others then blocked:=true;end;
 perform pg_temp.check_true(blocked,'recorded client signing timestamp cannot be edited');
 blocked:=false;begin update venue_agreement_signers set evidence='{}' where id=client_id;exception when others then blocked:=true;end;
 perform pg_temp.check_true(blocked,'recorded client verification evidence cannot be edited');
 blocked:=false;begin update venue_agreement_signers set status='pending' where id=client_id;exception when others then blocked:=true;end;
 perform pg_temp.check_true(blocked,'signed client cannot be reset to editable');
 blocked:=false;begin delete from venue_agreement_signers where id=client_id;exception when others then blocked:=true;end;
 perform pg_temp.check_true(blocked,'recorded client signature cannot be deleted');
 blocked:=false;begin perform venue_agreement_action('code','{"token_hash":"test-client-v1","code_hash":"replacement-code"}');exception when others then blocked:=true;end;
 perform pg_temp.check_true(blocked,'signed client cannot request another signing challenge');
 perform venue_agreement_action('code','{"token_hash":"test-venue-v1","code_hash":"venue-code"}');
 v:=venue_agreement_action('sign',jsonb_build_object('token_hash','test-venue-v1','code_hash','venue-code','signed_name','Test Venue','consent',true,'document_hash',v->>'document_hash'));
 perform pg_temp.check_true(v->>'status'='completed','both parties complete contract');
 perform pg_temp.check_true((select count(*)=2 from venue_agreement_signers where version_id=(v->>'id')::uuid and signed_at is not null),'two separate signature records');
 v2:=venue_agreement_action('draft',jsonb_build_object('response_id',rid,'change_summary','A test revision'));
 perform pg_temp.check_true((v2->>'version')::int=2,'revision increments version');
 v2:=venue_agreement_action('issue',jsonb_build_object('version_id',v2->>'id','expected_updated_at',v2->>'updated_at','tokens','[{"hash":"test-client-v2"},{"hash":"test-venue-v2"}]'::jsonb));
 perform pg_temp.check_true((select status='completed' from venue_agreement_versions where id=(v->>'id')::uuid),'old completed agreement retained while revision pending');
 perform pg_temp.check_true((select count(*)=0 from venue_agreement_signers where version_id=(v2->>'id')::uuid and signed_at is not null),'signatures never copied to revision');
 perform pg_temp.check_true(v2->>'document_hash'<>v->>'document_hash','revision has a different hash');
 perform venue_agreement_action('code','{"token_hash":"test-client-v2","code_hash":"client-v2-code"}');
 r:=venue_agreement_action('decline','{"token_hash":"test-client-v2","code_hash":"client-v2-code","reason":"Please change the test rental hours."}');
 perform pg_temp.check_true(r->>'status'='declined','verified client may decline');
 perform pg_temp.check_true((select status='completed' from venue_agreement_versions where id=(v->>'id')::uuid),'declined revision does not overwrite completed original');
 v2:=venue_agreement_action('draft',jsonb_build_object('response_id',rid,'change_summary','New test version after decline'));
 v2:=venue_agreement_action('issue',jsonb_build_object('version_id',v2->>'id','expected_updated_at',v2->>'updated_at','tokens','[{"hash":"test-client-v3"},{"hash":"test-venue-v3"}]'::jsonb));
 -- Expiry normally advances with clock time; a draft may use a past expiry
 -- only in this rollback test before the immutable issued snapshot is sealed.
 alter table venue_agreement_versions disable trigger venue_agreement_versions_immutable;
 update venue_agreement_versions set expires_at=now()-interval '1 minute' where id=(v2->>'id')::uuid;
 alter table venue_agreement_versions enable trigger venue_agreement_versions_immutable;
 r:=venue_agreement_action('view','{"token_hash":"test-client-v3"}');
 perform pg_temp.check_true(r->'version'->>'status'='expired','expired link cannot be signed');
 v2:=venue_agreement_action('draft',jsonb_build_object('response_id',rid,'change_summary','Final revised test agreement'));
 v2:=venue_agreement_action('issue',jsonb_build_object('version_id',v2->>'id','expected_updated_at',v2->>'updated_at','tokens','[{"hash":"test-client-v4"},{"hash":"test-venue-v4"}]'::jsonb));
 perform venue_agreement_action('code','{"token_hash":"test-client-v4","code_hash":"client-v4-code"}');
 perform venue_agreement_action('sign',jsonb_build_object('token_hash','test-client-v4','code_hash','client-v4-code','signed_name','Test Client','consent',true,'document_hash',v2->>'document_hash'));
 perform venue_agreement_action('code','{"token_hash":"test-venue-v4","code_hash":"venue-v4-code"}');
 v2:=venue_agreement_action('sign',jsonb_build_object('token_hash','test-venue-v4','code_hash','venue-v4-code','signed_name','Test Venue','consent',true,'document_hash',v2->>'document_hash'));
 perform pg_temp.check_true(v2->>'status'='completed','replacement completes with fresh signatures');
 perform pg_temp.check_true((select status='superseded' from venue_agreement_versions where id=(v->>'id')::uuid),'original superseded only after replacement complete');
 blocked:=false;begin update venue_agreement_versions set body='tamper' where id=(v2->>'id')::uuid;exception when others then blocked:=true;end;
 perform pg_temp.check_true(blocked,'database protects issued text even from accidental service writes');
 select id into client_id from venue_agreement_signers where version_id=(v2->>'id')::uuid and role='client';
 perform venue_agreement_action('revoke_link',jsonb_build_object('version_id',v2->>'id','signer_id',client_id));
 blocked:=false;begin perform venue_agreement_action('view','{"token_hash":"test-client-v4"}');exception when others then blocked:=true;end;
 perform pg_temp.check_true(blocked,'revoked links stop working');
 perform venue_agreement_action('link',jsonb_build_object('version_id',v2->>'id','signer_id',client_id,'hash','test-client-copy'));
 r:=venue_agreement_action('view','{"token_hash":"test-client-copy"}');
 perform pg_temp.check_true((r->>'can_sign')::boolean=false,'completed copy links cannot sign again');
 perform pg_temp.check_true((select status='signed' from venue_agreement_signers where id=client_id),'link replacement preserves signature');
 raise notice 'Contract integration tests passed: access, version locks, OTP limits, signing, countersigning, revision preservation, decline and expiry.';
end $$;
rollback;
